#pragma once

#include "Executor.h"

#include <condition_variable>
#include <cstddef>
#include <functional>
#include <future>
#include <memory>
#include <mutex>
#include <queue>
#include <stdexcept>
#include <thread>
#include <utility>
#include <vector>

// java.util.concurrent.ExecutorService 最小线程池桩。
// 固定大小线程池：mutex + condition_variable 保护的阻塞任务队列 + 工作线程组。
// - shutdown 后再提交任务抛 std::runtime_error；
// - shutdown 不阻塞，已入队任务继续执行完毕；
// - 析构时自动 shutdown 并 join 所有工作线程。
class ExecutorService : public Executor {
public:
    // 构造并启动 workers 个工作线程；0 表示使用硬件并发数（至少为 1）
    explicit ExecutorService(std::size_t workers = std::thread::hardware_concurrency());
    ~ExecutorService() override;

    ExecutorService(const ExecutorService&) = delete;
    ExecutorService& operator=(const ExecutorService&) = delete;

    // 提交无返回值任务（实现 Executor 接口）；shutdown 后抛 std::runtime_error
    void execute(std::function<void()> command) override;

    // 提交带返回值任务（对应 Java Callable），返回 future。
    // 模板方法，必须在头文件实现。
    template<typename T>
    std::shared_ptr<std::future<T>> submit(std::function<T()> task) {
        auto packaged = std::make_shared<std::packaged_task<T()>>(std::move(task));
        auto result = std::make_shared<std::future<T>>(packaged->get_future());
        // execute 在 shutdown 后会抛异常并向上传播，与 Java 拒绝语义一致
        execute([packaged]() { (*packaged)(); });
        return result;
    }

    // 停止接收新任务；已入队任务继续执行（虚函数，允许子类扩展关闭逻辑）
    virtual void shutdown();
    bool isShutdown() const;

private:
    // 工作线程主循环：阻塞取任务执行，shutdown 且队列空时退出
    void workerLoop();

    mutable std::mutex mutex_;
    std::condition_variable cv_;
    std::queue<std::function<void()>> tasks_;
    std::vector<std::thread> workers_;
    bool shutdown_ = false;
};

cpp_code:
#include "ExecutorService.h"

ExecutorService::ExecutorService(std::size_t workers) {
    if (workers == 0) workers = 1;  // 硬件并发数不可知时至少起一个线程
    workers_.reserve(workers);
    for (std::size_t i = 0; i < workers; ++i)
        workers_.emplace_back([this]() { workerLoop(); });
}

ExecutorService::~ExecutorService() {
    shutdown();
    for (auto& t : workers_) {
        if (t.joinable()) t.join();
    }
}

void ExecutorService::execute(std::function<void()> command) {
    {
        std::lock_guard<std::mutex> lock(mutex_);
        if (shutdown_)
            throw std::runtime_error("ExecutorService 已 shutdown，拒绝新任务");
        tasks_.push(std::move(command));
    }
    cv_.notify_one();
}

void ExecutorService::shutdown() {
    {
        std::lock_guard<std::mutex> lock(mutex_);
        shutdown_ = true;
    }
    cv_.notify_all();
}

bool ExecutorService::isShutdown() const {
    std::lock_guard<std::mutex> lock(mutex_);
    return shutdown_;
}

void ExecutorService::workerLoop() {
    for (;;) {
        std::function<void()> task;
        {
            std::unique_lock<std::mutex> lock(mutex_);
            cv_.wait(lock, [this]() { return shutdown_ || !tasks_.empty(); });
            if (tasks_.empty()) {
                if (shutdown_) return;  // shutdown 且队列已清空：线程退出
                continue;               // 虚假唤醒
            }
            task = std::move(tasks_.front());
            tasks_.pop();
        }
        task();
    }
}
